using Dapper;
using Monergy.Contracts;
using Monergy.Platform;
using Monergy.Services.FinancialRules.Infrastructure;
using Npgsql;
using Xunit;
namespace Monergy.Persistence.Tests;
public sealed partial class PersistentFoundationTests
{
    [Fact]
    public async Task CoverageReceiptSurvivesRestartIsTenantBoundIdempotentAndImmutable()
    {
        var rules=Configuration("FinancialRules");var customer="debt-coverage-"+Guid.NewGuid().ToString("N");var day=new DateOnly(2026,9,30);var income=new MonthlyCashflowLineDraft(Guid.NewGuid().ToString("N"),"INCOME","SALARY","Salary","10000.00","INR",day,"Customer reviewed");var expense=new MonthlyCashflowLineDraft(Guid.NewGuid().ToString("N"),"EXPENSE","HOUSEHOLD","Household","5000.00","INR",day,"Customer reviewed");var lines=new[]{income,expense};var position=new ReviewedMonthlyCashflowPosition("position-"+customer,Guid.NewGuid().ToString("N"),customer,new(day,"INR",lines,true,true,Household:"Customer household"),lines.Select(x=>new MonthlyCashflowPositionLine(x,null)).ToArray(),"actor-coverage",DateTimeOffset.UtcNow);var source=new MonthlyCashflowCalculation("cashflow-"+customer,Guid.NewGuid().ToString("N"),customer,position,MonthlyCashflowDefinition.Id,MonthlyCashflowDefinition.Version,MonthlyCashflowDefinition.DefinitionHash,MonthlyCashflowDefinition.Semantics,"CALCULATED","10000.00","5000.00","5000.00",Array.Empty<string>(),"actor-coverage",DateTimeOffset.UtcNow);var loan=new ReviewedLoanRecord("loan-1",Guid.NewGuid().ToString("N"),customer,new("Loan","Bank","HOME",10000,8000,8,2500,36,new(2026,1,1),new(2029,1,1),day,"fact-1",1),"INR","provenance-1","document-1","evidence-1","actor-coverage",DateTimeOffset.UtcNow,2,"ACTIVE",day);var emi=new MonthlyEmiShareCalculation("emi-share-"+customer,Guid.NewGuid().ToString("N"),customer,source,new[]{loan},true,MonthlyEmiShareDefinition.Id,MonthlyEmiShareDefinition.Version,MonthlyEmiShareDefinition.DefinitionHash,MonthlyEmiShareDefinition.Semantics,"CALCULATED","10000.00","2500.00","25.00",Array.Empty<string>(),"actor-coverage",DateTimeOffset.UtcNow);
        var operation=Guid.NewGuid().ToString("N");var value=new MonthlyDebtServiceCoverageCalculation("debt-coverage-"+Guid.NewGuid().ToString("N"),operation,customer,source,emi,true,MonthlyDebtServiceCoverageDefinition.Id,MonthlyDebtServiceCoverageDefinition.Version,MonthlyDebtServiceCoverageDefinition.DefinitionHash,MonthlyDebtServiceCoverageDefinition.Semantics,"CALCULATED","10000.00","5000.00","2500.00","5000.00","7500.00","3.00",Array.Empty<string>(),"actor-coverage",DateTimeOffset.UtcNow);const string fingerprint="fingerprint";
        await using(var repository=new PostgresMonthlyDebtServiceCoverageCalculations(rules)){Assert.True(MonthlyCashflowData.Same(value,await repository.CreateAsync("T001",customer,"actor-coverage",fingerprint,value,default)));Assert.True(MonthlyCashflowData.Same(value,await repository.CreateAsync("T001",customer,"actor-coverage",fingerprint,value,default)));}
        await using(var repository=new PostgresMonthlyDebtServiceCoverageCalculations(rules)){Assert.True(MonthlyCashflowData.Same(value,await repository.ReadAsync("T001",customer,value.CalculationId,default)));Assert.Single((await repository.ListAsync("T001",customer,null,default)).Items);Assert.Null(await repository.ReadAsync("T002",customer,value.CalculationId,default));Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>repository.CreateAsync("T001",customer,"actor-coverage","changed",value,default))).Status);}
        await using var sql=new NpgsqlConnection(Runtime("financial-rules"));var update=await Assert.ThrowsAsync<PostgresException>(()=>sql.ExecuteAsync("UPDATE financial_rules.monthly_debt_service_coverage_results SET payload=payload WHERE calculation_id=@Id;",new{Id=value.CalculationId}));Assert.Equal("42501",update.SqlState);var delete=await Assert.ThrowsAsync<PostgresException>(()=>sql.ExecuteAsync("DELETE FROM financial_rules.monthly_debt_service_coverage_results WHERE calculation_id=@Id;",new{Id=value.CalculationId}));Assert.Equal("42501",delete.SqlState);
    }
}
